<?php require 'config.php'; if(!isset($_SESSION['user'])){header('Location:login.php');exit;} $tag=$_GET['tag']??''; $sort=$_GET['sort']??'date_desc'; $per_page=max(1,(int)($_GET['per_page']??6)); $page=max(1,(int)($_GET['page']??1)); $offset=($page-1)*$per_page; $where=''; $params=[]; if($tag!==''){ $where='WHERE tag = ?'; $params[]=$tag; } switch($sort){ case 'date_asc': $order='ORDER BY created_at ASC'; break; case 'title_asc': $order='ORDER BY title ASC'; break; case 'title_desc': $order='ORDER BY title DESC'; break; default: $order='ORDER BY created_at DESC'; } $st=$pdo->prepare("SELECT COUNT(*) FROM projects $where"); $st->execute($params); $total=(int)$st->fetchColumn(); $pages=max(1,(int)ceil($total/$per_page)); $st=$pdo->prepare("SELECT * FROM projects $where $order LIMIT $per_page OFFSET $offset"); $st->execute($params); $projects=$st->fetchAll(); ?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Проекты</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="style.css"></head><body><?php include 'navbar.php'; ?><div class="container mt-4 fade-in"><div class="d-flex flex-wrap gap-2 align-items-end mb-3"><h2 class="me-auto">Мои проекты</h2><a href="project_add.php" class="btn btn-primary">Добавить проект</a></div><form method="get" class="row g-2 mb-3"><div class="col-md-3"><label class="form-label">Тег</label><select name="tag" class="form-select"><option value="" <?= $tag===''?'selected':'' ?>>Все</option><option value="web" <?= $tag==='web'?'selected':'' ?>>Web</option><option value="3D" <?= $tag==='3D'?'selected':'' ?>>3D</option><option value="other" <?= $tag==='other'?'selected':'' ?>>Другое</option></select></div><div class="col-md-3"><label class="form-label">Сортировка</label><select name="sort" class="form-select"><option value="date_desc" <?= $sort==='date_desc'?'selected':'' ?>>По дате (новые)</option><option value="date_asc" <?= $sort==='date_asc'?'selected':'' ?>>По дате (старые)</option><option value="title_asc" <?= $sort==='title_asc'?'selected':'' ?>>По алфавиту (А–Я)</option><option value="title_desc" <?= $sort==='title_desc'?'selected':'' ?>>По алфавиту (Я–А)</option></select></div><div class="col-md-2"><label class="form-label">На странице</label><select name="per_page" class="form-select"><?php foreach([6,9,12,24] as $opt): ?><option value="<?= $opt ?>" <?= $per_page==$opt?'selected':'' ?>><?= $opt ?></option><?php endforeach; ?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Применить</button></div></form><div class="row"><?php foreach($projects as $p): ?><div class="col-md-4"><div class="card mb-3"><?php if(!empty($p['image'])): ?><img src="uploads/<?= htmlspecialchars($p['image']) ?>" class="card-img-top" alt=""><?php endif; ?><div class="card-body"><span class="badge bg-secondary mb-2"><?= htmlspecialchars($p['tag'] ?: 'other') ?></span><h5 class="card-title"><?= htmlspecialchars($p['title']) ?></h5><p class="card-text"><?= nl2br(htmlspecialchars($p['description'])) ?></p><div class="d-flex flex-wrap gap-2"><?php if(!empty($p['link'])): ?><a href="<?= htmlspecialchars($p['link']) ?>" target="_blank" class="btn btn-outline-light btn-sm">Открыть</a><?php endif; ?><a href="project_edit.php?id=<?= $p['id'] ?>" class="btn btn-primary btn-sm">Редактировать</a><a href="project_delete.php?id=<?= $p['id'] ?>" class="btn btn-danger btn-sm" onclick="return confirm('Удалить проект?')">Удалить</a></div></div></div></div><?php endforeach; ?><?php if(!$projects): ?><div class="col-12"><div class="card p-3">Ничего не найдено. Измените фильтры.</div></div><?php endif; ?></div><?php if($pages>1): ?><nav class="mt-3"><ul class="pagination"><li class="page-item <?= $page<=1?'disabled':'' ?>"><a class="page-link" href="?page=<?= max(1,$page-1) ?>&tag=<?= urlencode($tag) ?>&sort=<?= urlencode($sort) ?>&per_page=<?= $per_page ?>">‹</a></li><?php for($i=1;$i<=$pages;$i++): ?><li class="page-item <?= $i==$page?'active':'' ?>"><a class="page-link" href="?page=<?= $i ?>&tag=<?= urlencode($tag) ?>&sort=<?= urlencode($sort) ?>&per_page=<?= $per_page ?>"><?= $i ?></a></li><?php endfor; ?><li class="page-item <?= $page>=$pages?'disabled':'' ?>"><a class="page-link" href="?page=<?= min($pages,$page+1) ?>&tag=<?= urlencode($tag) ?>&sort=<?= urlencode($sort) ?>&per_page=<?= $per_page ?>">›</a></li></ul></nav><?php endif; ?></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>